import { JSXElement } from '@babel/types';
import {
  arrow,
  autoPlacement,
  autoUpdate,
  computePosition,
  ComputePositionReturn,
  flip,
  limitShift,
  offset,
  shift,
} from '@floating-ui/dom';
import { Component, ComponentInterface, Element, Event, EventEmitter, h, Host, Prop, Watch } from '@stencil/core';
import { filter, fromEvent, merge, Subject, takeUntil } from 'rxjs';
import { CLOSE_BUTTON_LABEL } from '../../a11y';
import { TooltipPlacement } from '../../types';

/**
 * @slot default - default slot for the content which will be hovered
 * @slot tooltip - named slot 'tooltip', content for the tooltip
 */
@Component({
  tag: 'groupui-tooltip',
  styleUrl: 'tooltip.scss',
  shadow: true,
})
export class Tooltip implements ComponentInterface {
  /**
   * Represents the visibility of the tooltip. If set to true, the tooltip will ALWAYS be visible. If set to false, the tooltip will NEVER be visible. If not set, the tooltip will be visible on hover.
   */
  @Prop({ reflect: true }) readonly visible: boolean;

  /**
   * defines the position of the tooltip
   */
  @Prop({ reflect: true }) readonly position: TooltipPlacement = 'right';

  /**
   * toggles inverted variant
   */
  @Prop({ reflect: true }) readonly inverted: boolean;

  /**
   * tooltip only closes on 'x' pressed
   */
  @Prop({ reflect: true }) readonly sticky: boolean;

  /**
   * provide z-index if necessary (defaults to 500)
   */
  @Prop({ reflect: true }) readonly zIndex: number = 500;

  /**
   * sets a custom accessible text for the close button
   */
  @Prop({ reflect: true, attribute: 'a11y-label-close-button' }) readonly a11yLabelCloseButton: string;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * dispatched when the tooltip close button is clicked
   */
  @Event({ bubbles: false }) groupuiTooltipCloseClick: EventEmitter<CustomEvent<void>>;

  @Element() host: HTMLElement;

  private destroy: Subject<void>;

  private popoverRef?: HTMLElement;
  private tooltipArrowRef?: HTMLElement;

  private stopAutoUpdate: () => void;

  componentDidLoad() {
    if (this.getAnchorElement()) {
      this.listenToOpenTrigger();
      this.listenToCloseTriggers();
      this.listenToMouseEnter();
      this.listenToMouseLeave();
    }

    if (this.getAnchorElement() && this.popoverRef) {
      this.stopAutoUpdate = autoUpdate(this.getAnchorElement(), this.popoverRef, this.updateContentPosition);
    }
    this.onVisibleChange();
    this.groupuiDidLoad.emit();
  }

  private listenToMouseLeave() {
    fromEvent(this.getAnchorElement(), 'mouseleave')
      .pipe(takeUntil(this.destroy))
      .subscribe(() => {
        this.handleMouseLeave();
      });
  }

  private listenToMouseEnter() {
    fromEvent(this.getAnchorElement(), 'mouseenter')
      .pipe(takeUntil(this.destroy))
      .subscribe(() => {
        this.handleMouseEnter();
      });
  }

  private listenToOpenTrigger() {
    fromEvent(this.getAnchorElement(), 'focus')
      .pipe(takeUntil(this.destroy))
      .subscribe(() => {
        this.showTooltip();
      });
  }

  private listenToCloseTriggers() {
    const escapePressListener = fromEvent(this.host, 'keydown').pipe(
      filter((event: KeyboardEvent) => event.key === 'Escape')
    );
    const blurListener = fromEvent(this.getAnchorElement(), 'blur').pipe(filter(() => !this.sticky));

    merge(escapePressListener, blurListener)
      .pipe(takeUntil(this.destroy))
      .subscribe(() => {
        this.hideTooltip();
      });
  }

  connectedCallback() {
    this.destroy = new Subject<void>();
  }

  disconnectedCallback() {
    this.stopAutoUpdate && this.stopAutoUpdate();
    this.destroy.next();
    this.destroy.complete();
  }

  @Watch('position')
  onPositionChanged() {
    this.updateContentPosition();
  }

  @Watch('visible')
  onVisibleChange() {
    if (!this.popoverRef) {
      return;
    }
    if (this.visible) {
      this.showTooltip();
    } else {
      this.hideTooltip();
    }
  }

  private getAnchorElement = (): HTMLElement | null => {
    const defaultSlotElement: HTMLSlotElement | null = this.host.shadowRoot.querySelector('slot:not([name])');
    if (!defaultSlotElement) return null;
    const assignedElements = defaultSlotElement.assignedElements();
    if (assignedElements.length === 0) {
      const nodes = defaultSlotElement.assignedNodes();
      if (nodes.length === 0) {
        return null;
      }
      const firstTextNode = nodes[0];
      const replacementNode = document.createElement('span');
      replacementNode.innerHTML = firstTextNode.textContent;
      firstTextNode.parentElement.insertBefore(replacementNode, firstTextNode);
      firstTextNode.parentElement.removeChild(firstTextNode);
      return replacementNode;
    }

    return assignedElements[0] as HTMLElement;
  };

  private showTooltip = () => {
    if (this.visible === false || !this.popoverRef) {
      return;
    }
    this.stopAutoUpdate = autoUpdate(this.getAnchorElement(), this.popoverRef, this.updateContentPosition);
    this.popoverRef.showPopover && this.popoverRef.showPopover();
  };

  private hideTooltip = () => {
    if (this.visible) {
      return;
    }
    this.popoverRef && this.popoverRef.hidePopover && this.popoverRef.hidePopover();
    this.stopAutoUpdate && this.stopAutoUpdate();
  };

  private handleMouseEnter = () => {
    this.showTooltip();
  };

  private handleMouseLeave = () => {
    if (this.sticky) {
      return;
    }
    this.hideTooltip();
  };

  private handleCloseClicked = () => {
    this.groupuiTooltipCloseClick.emit();
    this.hideTooltip();
  };

  private updateContentPosition = async (): Promise<void> => {
    const positionData = await this.computeTooltipPosition();
    if (positionData) {
      this.setPopoverPosition(positionData);
      this.setArrowPosition(positionData);
    }
  };

  private async computeTooltipPosition(): Promise<ComputePositionReturn | undefined> {
    const popoverOffset = this.getPopoverOffset();
    if (!this.getAnchorElement() || !this.popoverRef) {
      return;
    }
    return await computePosition(this.getAnchorElement(), this.popoverRef, {
      placement: this.position !== 'auto' ? this.position : undefined,
      strategy: 'fixed',
      middleware: [
        ...(this.position === 'auto' ? [autoPlacement()] : [flip()]),
        offset(popoverOffset),
        shift({
          limiter: limitShift(),
        }),
        arrow({ element: this.tooltipArrowRef }),
      ],
    });
  }

  private getPopoverOffset(): number {
    return parseInt(getComputedStyle(this.host).getPropertyValue('--popover-offset'));
  }

  private getArrowOffsetPx(): string {
    return getComputedStyle(this.host).getPropertyValue('--arrow-offset');
  }

  private setPopoverPosition({ x, y }: ComputePositionReturn) {
    Object.assign(this.popoverRef.style, {
      left: `${x}px`,
      top: `${y}px`,
    });
  }

  private setArrowPosition({ middlewareData, placement }: ComputePositionReturn) {
    const { x, y } = middlewareData.arrow;
    const arrowOffset = this.getArrowOffsetPx();

    const staticSide = {
      top: 'bottom',
      right: 'left',
      bottom: 'top',
      left: 'right',
    }[placement.split('-')[0]];

    Object.assign(this.tooltipArrowRef.style, {
      left: x != null ? `${x}px` : '',
      top: y != null ? `${y}px` : '',
      right: '',
      bottom: '',
      [staticSide]: arrowOffset,
    });
  }

  private createCloseButton(): JSXElement {
    return this.sticky ? (
      <groupui-icon-button
        id="close-button"
        icon="close-16"
        onClick={this.handleCloseClicked}
        aria-label={this.a11yLabelCloseButton || CLOSE_BUTTON_LABEL}
        variant={this.inverted ? 'base' : 'inverted'}
      ></groupui-icon-button>
    ) : undefined;
  }

  render() {
    return (
      <Host>
        <slot aria-describedby="tooltip" />
        <div ref={(el) => (this.popoverRef = el)} id="tooltip-container" role="tooltip" popover="manual">
          <div id="tooltip">
            <slot name="tooltip" />
            {this.createCloseButton()}
          </div>
          <div ref={(el) => (this.tooltipArrowRef = el)} id="arrow" />
        </div>
      </Host>
    );
  }
}
